TASK AND SPECIFICATIONS
{
  "schema_version": 1,
  "id": "SELF010",
  "kind": "self_built",
  "title": "Latched alarm with acknowledgment and reannunciation",
  "difficulty": "medium",
  "provenance": {
    "source_type": "independent_synthesis",
    "source_file": "scripts/build_self_dataset.py",
    "source_index": 10,
    "adaptation": "Independently specified for this project; no public task was copied. The coding assistant chose the state variables, priority order and fixed scan traces, then reviewed the traces against a separate Python transition implementation.",
    "rationale": "A panel alarm retains the event after a fault clears, silences the horn after acknowledgment, and sounds again for a new fault edge.",
    "review": "Assistant consistency review of initialization, simultaneous commands, retained state and recovery boundaries; independent Python oracle checked against manual expected traces. Not an industrial safety certification or external expert review."
  },
  "requirements": "Initialize Alarm and Acknowledged FALSE and previous Fault FALSE. A Fault sets Alarm. A rising Fault also clears Acknowledged, taking priority over Ack on that scan. While Fault remains TRUE, Ack can set Acknowledged. When Fault is FALSE the alarm remains latched; Ack can acknowledge that retained alarm. Reset clears both values only when Fault is FALSE, taking priority over Ack then. A new Fault rising edge reannunciates even if an old alarm was already latched. Horn equals Alarm AND NOT Acknowledged. Always update the previous Fault sample.",
  "scenario": "A panel alarm retains the event after a fault clears, silences the horn after acknowledgment, and sounds again for a new fault edge.",
  "interface": [
    {
      "direction": "INPUT",
      "name": "Fault",
      "type": "BOOL",
      "description": "Current fault condition"
    },
    {
      "direction": "INPUT",
      "name": "Ack",
      "type": "BOOL",
      "description": "Acknowledge horn"
    },
    {
      "direction": "INPUT",
      "name": "Reset",
      "type": "BOOL",
      "description": "Clear a removed fault"
    },
    {
      "direction": "OUTPUT",
      "name": "Alarm",
      "type": "BOOL",
      "description": "Latched visible alarm"
    },
    {
      "direction": "OUTPUT",
      "name": "Acknowledged",
      "type": "BOOL",
      "description": "Alarm acknowledged"
    },
    {
      "direction": "OUTPUT",
      "name": "Horn",
      "type": "BOOL",
      "description": "Unacknowledged alarm horn"
    }
  ],
  "initial_conditions": {
    "Alarm": false,
    "Acknowledged": false,
    "previous_fault": false
  },
  "scan_semantics": "At scan k, sample every input once, read retained pre-state q[k], execute one transition, and observe outputs O[k] at the end of that same scan. Updated state becomes q[k+1]. Reset the instance before each test. Step 0 executes normally; initial conditions describe pre-state, not an extra delayed scan. All timing in this task is explicitly counted in invocations, not wall time.",
  "safety_priority": [
    "New fault edge reannunciates before Ack",
    "Reset only clears when Fault is absent",
    "Reset then precedes Ack"
  ],
  "assumptions": [],
  "atomic_propositions": {
    "Fault": "Current fault condition Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Ack": "Acknowledge horn Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Reset": "Clear a removed fault Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Alarm": "Latched visible alarm Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Acknowledged": "Alarm acknowledged Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Horn": "Unacknowledged alarm horn Boolean names are propositions; numeric names appear only inside defined predicates.",
    "first": "True only on the first invocation after resetting the FB instance.",
    "rise": "Fault & !qFault.",
    "qFault": "Previous Fault sample, initially FALSE.",
    "qAlarm": "Pre-scan Alarm.",
    "qAck": "Pre-scan Acknowledged."
  },
  "ltl": [
    {
      "id": "P1",
      "formula": "G(Horn <-> (Alarm & !Acknowledged))",
      "explanation": "Horn follows the latched acknowledgment state."
    },
    {
      "id": "P2",
      "formula": "G(Fault -> Alarm)",
      "explanation": "A present fault cannot be reset away."
    },
    {
      "id": "P3",
      "formula": "G(rise -> (Alarm & !Acknowledged & Horn))",
      "explanation": "Every new event annunciates despite simultaneous Ack."
    },
    {
      "id": "P4",
      "formula": "G((Reset & !Fault) -> (!Alarm & !Acknowledged & !Horn))",
      "explanation": "Reset clears a removed fault."
    },
    {
      "id": "P5",
      "formula": "G((!Fault & !Reset & qAlarm) -> Alarm)",
      "explanation": "Fault disappearance does not clear the visible alarm."
    },
    {
      "id": "P6",
      "formula": "G((!rise & !Reset & Ack & qAlarm) -> Acknowledged)",
      "explanation": "Acknowledgment silences a retained event."
    }
  ],
  "tests": [
    {
      "id": "annunciate",
      "purpose": "Acknowledge, fault clear and new event",
      "steps": [
        {
          "inputs": {
            "Fault": false,
            "Ack": false,
            "Reset": false
          },
          "expected": {
            "Alarm": false,
            "Acknowledged": false,
            "Horn": false
          }
        },
        {
          "inputs": {
            "Fault": true,
            "Ack": true,
            "Reset": false
          },
          "expected": {
            "Alarm": true,
            "Acknowledged": false,
            "Horn": true
          }
        },
        {
          "inputs": {
            "Fault": true,
            "Ack": true,
            "Reset": false
          },
          "expected": {
            "Alarm": true,
            "Acknowledged": true,
            "Horn": false
          }
        },
        {
          "inputs": {
            "Fault": false,
            "Ack": false,
            "Reset": false
          },
          "expected": {
            "Alarm": true,
            "Acknowledged": true,
            "Horn": false
          }
        },
        {
          "inputs": {
            "Fault": true,
            "Ack": false,
            "Reset": false
          },
          "expected": {
            "Alarm": true,
            "Acknowledged": false,
            "Horn": true
          }
        },
        {
          "inputs": {
            "Fault": false,
            "Ack": false,
            "Reset": true
          },
          "expected": {
            "Alarm": false,
            "Acknowledged": false,
            "Horn": false
          }
        }
      ]
    },
    {
      "id": "reset_priority",
      "purpose": "Present fault blocks reset; removed fault reset wins",
      "steps": [
        {
          "inputs": {
            "Fault": true,
            "Ack": false,
            "Reset": true
          },
          "expected": {
            "Alarm": true,
            "Acknowledged": false,
            "Horn": true
          }
        },
        {
          "inputs": {
            "Fault": true,
            "Ack": true,
            "Reset": true
          },
          "expected": {
            "Alarm": true,
            "Acknowledged": true,
            "Horn": false
          }
        },
        {
          "inputs": {
            "Fault": false,
            "Ack": true,
            "Reset": true
          },
          "expected": {
            "Alarm": false,
            "Acknowledged": false,
            "Horn": false
          }
        }
      ]
    }
  ]
}
